                .andExpect(status().isOk())
                .andExpect(jsonPath("$.revoked").value(true));
        // 幂等重试：返回原结果
        postJson("/api/grants/" + grantId + "/revoke",
                        Map.of("requestId", "req-" + p + "-rv"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.revoked").value(true));
        // 同 requestId 作用于不同授权：409
        long otherGrant = createGrant(channel, p + "movie");
