        }
        long id = repo.insertBreakin(channelId, asset.id(), atMs, request.requestId(), nowMs());
        return new BreakinResponse(id, channelId, asset.id(), request.at(), rating, window.map(RatingWindowRow::id).orElse(null));
    });
}
