    // ---------- 管控时段配置 ----------

    @Test
    void ratingWindowCrudValidationAndIdempotency() throws Exception {
        String p = prefix();
        String channel = newChannelWithRatedAssets(p);

        // 404：频道不存在
        postJson("/api/channels/" + p + "ghost/rating-windows",
                        windowBody("req-" + p + "-w0", DAY, T_08, T_12, "PG"))
