                        windowBody("req-" + p + "-w2", DAY, T_10, T_14, "G"))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.error").value("WINDOW_OVERLAP"));
        // 失败不占键：同 requestId 换合法参数成功（端点相接合法）
